256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner != null) {
262	            Pet pet = owner.getPet(petId);
263	            if (pet != null) {
264	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
265	            }
266	        }
267	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
268	    }
269	
270	    /** Matches a well-formed postcode: exactly 4 digits. */
271	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
272	
273	    /**
274	     * Region -> inclusive 4-digit postcode range {low, high}. A city's region is derived from the
275	     * fixed city-to-region table ({@link Owner#getRegion()}); a region absent from this map (i.e.
276	     * {@code UNKNOWN}) carries no range rule and accepts any 4-digit postcode.
277	     */
278	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
279	        "NSW", new int[] {2000, 2099},
280	        "VIC", new int[] {3000, 3099},
281	        "QLD", new int[] {4000, 4099});
282	
283	    /**
284	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
285	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
286	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
287	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode.
288	     */
289	    private static boolean isPostcodeValidForCity(Owner owner) {
290	        String postcode = owner.getPostcode();
291	        if (postcode == null) {
292	            return true;
293	        }
294	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
295	            return false;
296	        }
297	        int[] range = REGION_POSTCODE_RANGES.get(owner.getRegion());
298	        if (range == null) {
299	            return true;
300	        }
301	        int value = Integer.parseInt(postcode);
302	        return value >= range[0] && value <= range[1];
303	    }
304	
305	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
306	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
307	
308	    /**
309	     * Required national-number length per country code: '+61' (Australia) expects 9 national
310	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
311	     * national part is not the required length is rejected.
312	     */
313	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
314	        "+61", 9, "+1", 10);
315	
316	    /**
317	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
318	     * code are kept when present; otherwise country code '+61' is assumed and a single
319	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
320	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
321	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
322	     * Returns {@code null} when the number cannot form a valid E.164 value.
323	     */
324	    private static String normalizeTelephone(String telephone) {
325	        if (telephone == null) {
326	            return null;
327	        }
328	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
329	        String e164;
330	        if (cleaned.startsWith("+")) {
331	            e164 = cleaned;
332	        } else {
333	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
334	            e164 = "+61" + national;
335	        }
336	        if (!E164_PATTERN.matcher(e164).matches()) {
337	            return null;
338	        }
339	        return hasValidNationalNumberLength(e164) ? e164 : null;
340	    }
341	
342	    /**
343	     * Whether the national number of a well-formed E.164 value has the length required for its
344	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
345	     * per-country length rule and are accepted.
346	     */
347	    private static boolean hasValidNationalNumberLength(String e164) {
348	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
349	            String countryCode = entry.getKey();
350	            if (e164.startsWith(countryCode)) {
351	                return e164.length() - countryCode.length() == entry.getValue();
352	            }
353	        }
354	        return true;
355	    }
356	
357	    /**
358	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
359	     * code, membership number, household id, namesake count and household member count. Each is
360	     * derived from the owner's already-normalized fields and the existing owner population, so this
361	     * must run before the owner is saved, while the counts still exclude the owner being created.
362	     */
363	    private void assignRegistrationAttributes(Owner owner) {
364	        owner.setCustomerCode(generateCustomerCode(owner));
365	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
366	        owner.setHouseholdId(householdId(owner));
367	        owner.setNamesakeCount(countNamesakes(owner));
368	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
369	    }
370	
371	    /**
372	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
373	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
374	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
375	     * owner's last name (e.g. 'NSW-1A2B3C4D'). There are no sequence numbers: the identity is a pure
376	     * function of the region and the (telephone, last name) pair.
377	     */
378	    private String generateCustomerCode(Owner owner) {
379	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
380	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
381	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
382	        return owner.getRegion() + "-" + hash8;
383	    }
384	
385	    /**
386	     * The number of existing owners registered in {@code city}, compared case-insensitively
387	     * with collapsed whitespace.
388	     */
389	    private int countOwnersInCity(String city) {
390	        String normalized = normalizeHouseholdField(city);
391	        return (int) this.clinicService.findAllOwners().stream()
392	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
393	            .count();
394	    }
395	
396	    /**
397	     * The effective registration date to store for a new owner: the date supplied on the request
398	     * when present, otherwise the current server date, in either case rolled forward to a business
399	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
400	     * This single point of resolution is what every registration-date-derived value (the stored
401	     * date, the membership number's year segment, the per-day create-limit) is computed from.
402	     */
403	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
404	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
405	        return toBusinessDay(date);
406	    }
407	
408	    /**
409	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
410	     * following Monday; a weekday is returned unchanged.
411	     */
412	    private static LocalDate toBusinessDay(LocalDate date) {
413	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
414	            date = date.plusDays(1);
415	        }
416	        return date;
417	    }
418	
419	    /**
420	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
421	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
422	     */
423	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
424	        String yy = String.format("%02d", registrationDate.getYear() % 100);
425	        return customerCode + "-M" + yy;
426	    }
427	
428	    /**
429	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
430	     * last name, compared case-insensitively.
431	     */
432	    private int countNamesakes(Owner owner) {
433	        String firstName = normalizeHouseholdField(owner.getFirstName());
434	        String lastName = normalizeHouseholdField(owner.getLastName());
435	        return (int) this.clinicService.findAllOwners().stream()
436	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
437	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
438	            .count();
439	    }
440	
441	    /**
442	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
443	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
444	     * unusually high daily signup volume.
445	     */
446	    private boolean isBulkSignupWarning() {
447	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
448	    }
449	
450	    /** The number of existing owners whose registration date is {@code date}. */
451	    private int countOwnersRegisteredOn(LocalDate date) {
452	        return (int) this.clinicService.findAllOwners().stream()
453	            .filter(existing -> date.equals(existing.getRegistrationDate()))
454	            .count();
455	    }
456	
457	    /**
458	     * The single derived key all duplicate detection flows through, formed from the owner's
459	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
460	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
461	     * id is derived, so the household segment is empty at that point. Because the telephone is part
462	     * of the key, two owners in the same household with different telephones resolve to different
463	     * keys and are both allowed.
464	     */
465	    private static String identityKey(Owner owner) {
466	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
467	        String email = owner.getEmail() == null ? "" : owner.getEmail();
468	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
469	        return telephone + "|" + email + "|" + household;
470	    }
471	
472	    /**
473	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
474	     * duplicate condition: the previously separate telephone, email and household checks are now all
475	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
476	     * trips it is rejected with {@code 409 CONFLICT}.
477	     */
478	    private boolean isDuplicate(Owner owner) {
479	        String key = owner.getIdentityKey();
480	        return this.clinicService.findAllOwners().stream()
481	            .map(Owner::getIdentityKey)
482	            .filter(existing -> existing != null)
483	            .anyMatch(key::equals);
484	    }
485	
486	    /** Common street-type abbreviations expanded during address normalization. */
487	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
488	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
489	
490	    /**
491	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
492	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
493	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
494	     * string when {@code address} is null or blank after normalization.
495	     */
496	    private static String normalizeAddress(String address) {
497	        if (address == null) {
498	            return "";
499	        }
500	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
501	        if (collapsed.isEmpty()) {
502	            return "";
503	        }
504	        StringBuilder sb = new StringBuilder(collapsed.length());
505	        for (String token : collapsed.split(" ")) {
506	            if (sb.length() > 0) {
507	                sb.append(' ');
508	            }
509	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
510	        }
511	        return sb.toString();
512	    }
513	
514	    /**
515	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
516	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
517	     */
518	    private static String normalizeHouseholdField(String value) {
519	        if (value == null) {
520	            return "";
521	        }
522	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
523	    }
524	
525	    /**
526	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
527	     * same address compared case-insensitively with collapsed whitespace.
528	     */
529	    private List<Owner> findHousemates(Owner owner) {
530	        String lastName = normalizeHouseholdField(owner.getLastName());
531	        String address = normalizeHouseholdField(owner.getAddress());
532	        return this.clinicService.findAllOwners().stream()
533	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
534	                && normalizeHouseholdField(existing.getAddress()).equals(address))
535	            .toList();
536	    }
537	
538	    /**
539	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
540	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
541	     */
542	    private int countHouseholdMembers(Owner owner) {
543	        return findHousemates(owner).size() + 1;
544	    }
545	
546	    /**
547	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
548	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
549	     * deterministically from those normalized fields so housemates always resolve to the same value,
550	     * regardless of registration order.
551	     */
552	    private static String householdId(Owner owner) {
553	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
554	            + normalizeHouseholdField(owner.getAddress());
555	        return sha256Hex(key).substring(0, 24);
556	    }
557	
558	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
559	    private static String sha256Hex(String input) {
560	        try {
561	            byte[] digest = MessageDigest.getInstance("SHA-256")
562	                .digest(input.getBytes(StandardCharsets.UTF_8));
563	            StringBuilder sb = new StringBuilder(digest.length * 2);
564	            for (byte b : digest) {
565	                sb.append(String.format("%02X", b));
566	            }
567	            return sb.toString();
568	        }
569	        catch (NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 not available", e);
571	        }
572	    }
573	}
